INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('chu-west','西楚','["楚"]',NULL,NULL,'cn','east_asia',-206,1,NULL,'year',-202,12,NULL,'month',-2460,-2401,'ochre',NULL,NULL,'项羽分封后自立西楚霸王，都彭城；垓下败亡，政权终结。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('han-east','东汉','["汉","后汉"]',NULL,NULL,'cn','east_asia',25,8,NULL,'month',220,11,NULL,'month',307,2650,'ochre',NULL,NULL,'刘秀于25年重建汉室、定都洛阳，初期整顿吏治并恢复社会生产，明、章时期国势较盛，经营西域亦有进展。和帝以后外戚与宦官交替掌权，黄巾起事及州郡割据削弱朝廷；献帝于220年禅位曹丕，东汉结束。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('han-gengshi','更始','["汉","玄汉"]',NULL,NULL,'cn','east_asia',23,1,NULL,'year',25,10,NULL,'month',276,309,'ochre',NULL,NULL,'绿林军拥立更始帝刘玄，复汉号；赤眉入长安后刘玄降被杀。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('han-west','西汉','["汉","前汉"]',NULL,NULL,'cn','east_asia',-202,2,NULL,'month',9,1,NULL,'year',-2411,108,'ochre',NULL,NULL,'刘邦在楚汉战争后于前202年称帝，定都长安，建立以郡县为骨干、兼行诸侯王国的统治秩序。文景时期休养生息，武帝时中央集权与疆域扩展并进；宣帝以后外戚势力渐强，王莽于9年代汉，西汉告终。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('xin','新','["新","新莽"]',NULL,NULL,'cn','east_asia',9,1,NULL,'month',23,10,NULL,'month',108,285,'ochre',NULL,NULL,'王莽凭外戚身份进入西汉权力核心，先后任大司马、辅政和居摄。9年取代汉室，建立新朝，以长安为都；改制及连年灾荒、征发加剧社会冲突，绿林、赤眉等起兵。23年绿林军攻入长安，王莽被杀，新朝结束。');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ban-chao','班超','han-east','[]',NULL,NULL,32,1,NULL,'year',102,1,NULL,'year','["外交家","军事家"]','东汉将领、外交家，字仲升，扶风安陵人，班彪之子、班固之弟。永平年间投笔从戎出使西域，经营西域三十余年，击退匈奴势力并促使诸国归附，晚年返洛阳。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/班超"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('cai-lun','蔡伦','han-east','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["发明家"]','东汉宦官，改进造纸术，纸张普及为之勃兴；《后汉书》记其改进造纸并于元兴元年奏报；纸张此前已出现，他主要推动工艺改良与推广。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/蔡伦"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chen-sheng','陈胜','qin','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["起义领袖"]','秦末起义领袖，阳城人，原为屯长。前209年与吴广在大泽乡起兵，建立张楚政权并称王，揭开秦末大规模反秦战争；起义迅速扩展后因内部矛盾而失败。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/陈胜"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('dong-zhongshu','董仲舒','han-west','[]',NULL,NULL,-179,1,NULL,'year',-104,1,NULL,'year','["思想家"]','西汉思想家，广川人，治《春秋公羊传》。汉武帝时上《天人三策》，阐发天人感应与大一统思想；“罢黜百家、独尊儒术”是后世对汉代政策变化的概括，不宜简单归为一人主张。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/董仲舒"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('dou-taihou','窦太后','han-west','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["太后","政治家"]','汉文帝皇后，景帝生母，崇尚黄老，文景之治重要推手；景帝时反对削藩，武帝初年仍影响朝政；其主张与黄老思想关系密切。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/窦太后"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('han-xin','韩信','han-west','[]',NULL,NULL,-231,1,NULL,'year',-196,1,NULL,'year','["军事家"]','汉初大将，破赵燕齐楚，垓下围项羽，后遭诛；因萧何推荐而受刘邦拜将，统军取关中、破赵齐；前196年被吕后与萧何诱杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/韩信"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('huo-guang','霍光','han-west','[]',NULL,NULL,NULL,NULL,NULL,NULL,-68,1,NULL,'year','["政治家"]','汉昭帝辅政大臣，废立昌邑王、拥立宣帝，权倾朝野；昭帝、宣帝时期长期掌政，霍氏家族显贵；其死后家族因谋反案被诛。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/霍光"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('huo-qubing','霍去病','han-west','[]',NULL,NULL,-140,1,NULL,'year',-117,1,NULL,'year','["军事家"]','汉武帝时名将，河西、漠北连破匈奴，封冠军侯；出击河西后为汉朝控制走廊地区，漠北之战封狼居胥；前117年病逝，年仅二十四岁。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/霍去病"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-si','李斯','qin','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家"]','秦相，助嬴政统一，推行郡县、书同文，后因赵高陷害被诛；秦始皇死后与赵高拥立胡亥，最终被构陷，在咸阳受五刑并夷三族。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李斯"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liang-taihou','梁太后','han-east','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["太后","政治家"]','东汉顺帝皇后梁妠，梁商之女。顺帝死后以皇太后身份临朝，先后拥立冲帝、质帝与桓帝，后归政；质帝实际为其兄梁冀下毒所杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/梁妠"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-ao','刘骜','han-west','[]',NULL,NULL,-51,1,NULL,'year',-7,1,NULL,'year','["皇帝"]','刘骜是元帝之子，继位后外戚王氏势力持续增长，朝政多由外戚与近臣参与。他无子嗣，由侄子刘欣继承皇位；其在位后期的权力结构为王莽掌政创造了条件。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/汉成帝"}]','孝成皇帝',NULL,'汉成帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-bang','刘邦','han-west','[]',NULL,NULL,-256,1,NULL,'year',-195,1,NULL,'year','["皇帝"]','沛县人，曾任秦泗水亭长。前209年秦末起事，受沛县父老拥立，后加入项梁领导的反秦军；前207年先入关中，接受秦王子婴投降。项羽分封时获汉中、巴蜀，随后夺取关中并与项羽争战；前202年垓下战后称帝，建立汉朝，后定都长安。平定异姓诸侯王并分封同姓王，形成郡国并行的统治格局。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘邦"},{"label":"漢書/卷001下","url":"https://zh.wikisource.org/wiki/漢書/卷001下"},{"label":"交接日期复核来源","url":"https://en.wikipedia.org/wiki/Liu_Bang"}]','高皇帝','太祖','汉高祖','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-bao','刘保','han-east','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','刘保是安帝与宫人李氏之子，曾被邓氏外戚废为济阴王；安帝死后，宦官迎立他为帝。他恢复皇位后任用宦官，梁氏外戚随后长期掌权，顺帝末年各地灾荒与民变频仍。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/汉顺帝"}]','孝顺皇帝',NULL,'汉顺帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-bian','刘辩','han-east','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','刘辩是灵帝与何皇后之子，灵帝去世后由大将军何进等拥立为帝。宦官诛杀何进后，董卓入京并废刘辩为弘农王，改立其弟刘协；刘辩不久被董卓杀害。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/汉少帝刘辩"}]',NULL,NULL,'汉后少帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-bing','刘炳','han-east','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','刘炳是顺帝之子，幼年即位，朝政由梁太后及其兄梁冀把持。他在位仅数月便去世，继位人选遂落入梁冀控制之下，东汉皇位此后长期受外戚干预。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/汉冲帝"}]','孝冲皇帝',NULL,'汉冲帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-che','刘彻','han-west','[]',NULL,NULL,-156,1,NULL,'year',-87,1,NULL,'year','["皇帝"]','刘彻为景帝之子，继位后加强中央集权，推行推恩令、盐铁专卖等措施，并以儒学确立国家礼制核心。他多次对匈奴用兵、派遣张骞出使西域，扩大汉朝影响；长期战争也加重财政与民间负担。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/汉武帝"}]','孝武皇帝','世宗','汉武帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-fuling','刘弗陵','han-west','[]',NULL,NULL,-94,1,NULL,'year',-74,1,NULL,'year','["皇帝"]','刘弗陵是武帝幼子，八岁即位，霍光等大臣辅政。昭帝时期整顿武帝晚年政策、减轻赋役，并在对匈奴关系上取得进展；其统治与继位的宣帝时期常合称“昭宣之治”。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/汉昭帝"}]','孝昭皇帝',NULL,'汉昭帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-gong','刘？','han-west','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','西汉前少帝，名不详。汉惠帝去世后幼年即位，吕太后临朝称制。据《史记》，得知生母被杀、自己并非张皇后亲子后出怨言，被吕太后幽禁。前184年被废黜并杀害，吕太后另立常山王刘弘为帝。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/西汉前少帝"},{"label":"《史记·吕太后本纪》","url":"https://zh.wikisource.org/wiki/史記/卷009"},{"label":"《汉书·高后纪》","url":"https://zh.wikisource.org/wiki/漢書/卷003"}]',NULL,NULL,'前少帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-he','刘贺','han-west','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','刘贺是武帝之孙、昌邑王，昭帝去世后由霍光等迎立为帝。因即位后行为失当及与辅政大臣冲突，在位二十七日即被废，返回封国，后世称汉废帝或海昏侯。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘贺"}]','海昏侯',NULL,'汉废帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-heng','刘恒','han-west','[]',NULL,NULL,-203,1,NULL,'year',-157,1,NULL,'year','["皇帝"]','刘恒是刘邦之子，原为代王，在吕氏集团覆灭后由功臣迎立为帝。文帝崇尚俭约、减轻赋役并放宽刑罚，与景帝共同开创“文景之治”，为汉朝积累财力与社会稳定。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/汉文帝"}]','孝文皇帝','太宗','汉文帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-hong','刘宏','han-east','[]',NULL,NULL,157,1,NULL,'year',189,1,NULL,'year','["皇帝"]','刘宏是章帝玄孙，桓帝死后由窦太后及其父窦武等拥立。灵帝时期宦官干政、卖官与党争加深，184年黄巾起事爆发；为应对战乱而扩张的州牧与地方军力，推动中央权威瓦解。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/汉灵帝"}]','孝灵皇帝',NULL,'汉灵帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-hong-shao','刘弘','han-west','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','刘弘是吕太后去世后由吕氏拥立的后少帝，延续惠帝一系名义上的皇位。周勃、陈平等诛灭诸吕后废黜刘弘，迎立刘邦之子代王刘恒，汉廷由此转入文帝一系。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘弘"}]',NULL,NULL,'汉后少帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-hu','刘祜','han-east','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','刘祜是章帝之孙、清河孝王刘庆之子，由邓太后选立为帝。邓太后去世后他亲政，重新启用宦官并处置邓氏；其晚年西羌战事与宫廷权力斗争加重。安帝死后，北乡侯刘懿即位；刘懿病逝后，济阴王刘保在宦官政变中即位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/汉安帝"}]','孝安皇帝',NULL,'汉安帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-kan','刘衎','han-west','[]',NULL,NULL,-9,1,NULL,'year',6,1,NULL,'year','["皇帝"]','刘衎是元帝之孙、平帝，年幼即位，朝政由辅政大司马王莽控制。王莽逐步扩大权力并于9年受禅代汉；刘衎在位期间去世，西汉皇统随新朝建立而中断。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/汉平帝"}]','孝平皇帝',NULL,'汉平帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-long','刘隆','han-east','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','刘隆是和帝幼子，和帝去世后由邓太后拥立，出生百余日即位。邓太后临朝辅政，刘隆不满周岁便去世，是东汉在位时间最短的皇帝之一；其后由安帝刘祜继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/汉殇帝"}]','孝殇皇帝',NULL,'汉殇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-qi','刘启','han-west','[]',NULL,NULL,-188,1,NULL,'year',-141,1,NULL,'year','["皇帝"]','刘启为文帝之子，承继文帝的节俭与轻徭政策。即位初年平定吴楚等七国之乱，随后削弱诸侯王权、加强中央控制；其统治与文帝时期合称“文景之治”。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/汉景帝"}]','孝景皇帝',NULL,'汉景帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-shi','刘奭','han-west','[]',NULL,NULL,-75,1,NULL,'year',-33,1,NULL,'year','["皇帝"]','刘奭为宣帝与许平君之子，承继皇位后重用儒臣，尝试以宽政和经学整顿朝政。他在位时朝廷外戚与近臣影响上升，西汉由宣帝时期的强势逐渐转向皇权受制。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/汉元帝"}]','孝元皇帝',NULL,'汉元帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-xie','刘协','han-east','[]',NULL,NULL,181,1,NULL,'year',234,1,NULL,'year','["皇帝"]','刘协是灵帝之子，董卓废少帝后拥立他为献帝，并迁都长安。曹操迎献帝至许县后控制朝廷，皇帝名义仍存而政权实权旁落；220年刘协禅位曹丕，东汉结束。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/汉献帝"}]','孝献皇帝',NULL,'汉献帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-xin','刘欣','han-west','[]',NULL,NULL,-27,1,NULL,'year',-1,1,NULL,'year','["皇帝"]','刘欣为元帝之孙、定陶恭王刘康之子，经成帝立为继承人后即位。他曾试图削弱王氏外戚，并宠信董贤；在位六年无子，死后由年幼的刘衎继位，王莽继续掌握朝政。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/汉哀帝"}]','孝哀皇帝',NULL,'汉哀帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-xiu','刘秀','han-east','[]',NULL,NULL,-5,1,NULL,'year',57,1,NULL,'year','["皇帝"]','汉景帝后裔，南阳人。22年与兄刘縯起兵，次年参与昆阳之战，击败新莽大军；更始帝杀刘縯后，刘秀奉命赴河北，联合地方豪强并击败王郎，逐渐形成独立势力。25年称帝重建汉朝，以洛阳为都，至36年平定公孙述，完成统一。其后整顿吏治、减轻徭役，恢复汉朝统治。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘秀"}]','光武皇帝','世祖','汉光武帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-xuan','刘玄','han-gengshi','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','汉景帝后裔，曾加入绿林军。23年绿林各部为联合反莽力量而拥立他为更始帝；刘秀等在昆阳击败新军，绿林军继而攻入长安，王莽被杀。刘玄先都洛阳，后迁长安，未能稳固各部关系。25年赤眉军入关，他投降后被杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/更始帝"},{"label":"《史记·项羽本纪》（维基文库）","url":"https://zh.wikisource.org/wiki/史記/卷07"},{"label":"《史记·秦始皇本纪》（维基文库）","url":"https://zh.wikisource.org/wiki/史記/卷06"},{"label":"人物生平与建国经历","url":"https://zh.wikipedia.org/wiki/刘玄"}]',NULL,NULL,'更始帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-xun','刘询','han-west','[]',NULL,NULL,-91,1,NULL,'year',-48,1,NULL,'year','["皇帝"]','刘询是武帝曾孙，幼年因巫蛊之祸牵连，在民间长大，后由霍光等迎立为帝。他亲自理政后整顿吏治、抑制豪强，恢复社会经济，并支持赵充国等经营西北，西汉国势再度稳定。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/汉宣帝"}]','孝宣皇帝',NULL,'汉宣帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-yi-shao','刘懿','han-east','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','刘懿是济北惠王刘寿之子，安帝去世后由阎太后及其外戚拥立为帝，在位约七个月。刘懿病逝后，宦官与朝臣迎立被废为济阴王的刘保，是为顺帝；刘懿未留下年号。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/汉少帝"}]',NULL,NULL,'汉前少帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-ying','刘盈','han-west','[]',NULL,NULL,-211,1,NULL,'year',-188,1,NULL,'year','["皇帝"]','刘盈为刘邦与吕雉之子，继位为惠帝，在位时吕太后实际主政。他延续汉初轻徭薄赋政策，废除秦代部分严刑，与民休息；其早逝后吕氏势力一度掌权。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘盈"}]','孝惠皇帝',NULL,'汉惠帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-zhao','刘肇','han-east','[]',NULL,NULL,79,1,NULL,'year',106,1,NULL,'year','["皇帝"]','刘肇是章帝之子，幼年即位，由窦太后及窦氏外戚辅政；成年后与宦官郑众合作，清除窦氏势力。他在位时派班超巩固西域经营，汉朝国力仍盛，但外戚、宦官参与朝政的局面进一步形成。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/汉和帝"}]','孝和皇帝',NULL,'汉和帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-zhi','刘志','han-east','[]',NULL,NULL,132,1,NULL,'year',168,1,NULL,'year','["皇帝"]','刘志是章帝曾孙、蠡吾侯之子，梁冀拥立他为桓帝；桓帝后来借助宦官诛灭梁冀及其党羽。此后宦官集团势力膨胀，党锢之祸加剧士人冲突，东汉朝廷的控制力持续衰退。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/汉桓帝"}]','孝桓皇帝',NULL,'汉桓帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-zhuang','刘庄','han-east','[]',NULL,NULL,28,1,NULL,'year',75,1,NULL,'year','["皇帝"]','刘庄是光武帝与阴丽华之子，继位后延续光武时期的行政整顿，重视法令与吏治，并支持班超经营西域。他在位时汉朝国力较强，明帝与其子章帝的统治常被视作东汉前期的稳定时期。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/汉明帝"}]','孝明皇帝','显宗','汉明帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-zuan','刘缵','han-east','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','刘缵是章帝玄孙，冲帝去世后由梁冀迎立为帝。质帝年幼而聪敏，曾当面称梁冀为“跋扈将军”，不久便遭梁冀毒杀；梁氏随后拥立刘志。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/汉质帝"}]','孝质皇帝',NULL,'汉质帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-zuo','刘炟','han-east','[]',NULL,NULL,57,1,NULL,'year',88,1,NULL,'year','["皇帝"]','刘炟为明帝之子，继位后承续明帝的政务制度，重视儒学与经术，并维持对西域的经营。章帝时期社会相对安定；其子和帝年幼即位，朝廷此后逐渐受外戚辅政影响。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/汉章帝"}]','孝章皇帝','肃宗','汉章帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('lv-zhi','吕雉','han-west','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇后","政治家"]','汉高祖刘邦皇后，名雉，字娥姁。刘邦去世后，她以皇太后身份临朝称制，扶立惠帝并掌握朝政，分封吕氏外戚；其死后吕氏势力被周勃、陈平等诛灭。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/吕雉"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ruzi-ying','刘婴','han-west','[]',NULL,NULL,NULL,NULL,NULL,NULL,24,1,NULL,'year','["君主"]','刘婴是平帝死后由王莽立为皇太子的刘氏宗室，年幼时被称作“孺子”，始终未正式即皇帝位。王莽于9年建立新朝后将他废置；更始政权兴起后，刘婴在长安被杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/孺子婴"}]',NULL,NULL,'孺子婴','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('si-ma-qian','司马迁','han-west','[]',NULL,NULL,-145,1,NULL,'year',-86,1,NULL,'year','["史学家"]','汉武帝时太史令，著史记，中国第一部纪传体通史；《史记》含本纪、表、书、世家、列传五体，司马迁称承继父亲遗志完成此书。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/司马迁"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wang-mang','王莽','xin','[]',NULL,NULL,-45,1,NULL,'year',23,1,NULL,'year','["皇帝"]','汉元帝皇后王政君之侄。前8年任大司马，前1年汉哀帝死后再掌朝政，辅佐年幼的平帝；平帝死后立孺子婴，自居摄政。9年以符命等为依据取代汉朝，国号新。其土地、货币等改革遇到阻力，灾荒与征敛又激化地方反抗；23年长安被攻陷，王莽被杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/王莽"}]',NULL,NULL,'','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wang-zhaojun','王昭君','han-west','[]',NULL,NULL,-52,1,NULL,'year',-15,1,NULL,'year','["后妃"]','西汉宫人，名嫱，字昭君，南郡秭归人。汉元帝时出塞，与匈奴呼韩邪单于和亲，促进汉匈关系稳定；正史称其为“昭君”，后世文学对其经历多有演绎。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/王昭君"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wei-bao','魏豹','han-gengshi','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["诸侯"]','魏豹是魏王魏咎之弟，秦末被项羽立为魏王。楚汉战争中他先从汉、后叛汉，韩信攻取魏地后将其俘杀，魏国复立政权随之消失。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/魏王豹"},{"label":"《史记·项羽本纪》（维基文库）","url":"https://zh.wikisource.org/wiki/史記/卷07"},{"label":"《史记·秦始皇本纪》（维基文库）","url":"https://zh.wikisource.org/wiki/史記/卷06"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wei-qing','卫青','han-west','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["军事家"]','西汉名将，字仲卿，河东平阳人，为卫子夫之弟。汉武帝时多次率军出击匈奴，收复河南地并深入漠北，官至大司马大将军；其外甥霍去病亦为名将。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/卫青"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wu-guang','吴广','qin','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["起义领袖"]','秦末起义领袖，阳夏人，任屯长时与陈胜率戍卒在大泽乡起兵。陈胜称王后他任假王，率军攻荥阳，后被部将田臧杀害；起义成为秦朝覆亡的重要开端。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/吴广"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xiang-liang','项梁','chu-west','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["起义领袖","将领"]','项羽叔父，会稽起兵反秦，立楚怀王，战死于定陶；率项氏部众起兵反秦并拥立楚怀王，前208年在定陶遭秦军夜袭战死。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/项梁"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xiang-yu','项羽','chu-west','[]',NULL,NULL,-232,1,NULL,'year',-202,1,NULL,'year','["霸王","军事家"]','楚将项燕之孙，名籍。前209年随叔父项梁在会稽起兵；项梁败死后，前207年杀宋义夺取军权，在巨鹿击败秦军并迫章邯投降。入关后主持分封，前206年自称西楚霸王，以彭城为都。与刘邦争夺天下，前202年垓下战败后在乌江自刎。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/项羽"},{"label":"《史记·项羽本纪》（维基文库）","url":"https://zh.wikisource.org/wiki/史記/卷07"}]',NULL,NULL,'西楚霸王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xiao-he','萧何','han-west','[]',NULL,NULL,-257,1,NULL,'year',-193,1,NULL,'year','["政治家"]','汉初相国，定都长安、制律令，与韩信、张良并称三杰；刘邦入关后保护秦朝图籍，为汉初掌握户籍、地理和郡县资料提供基础。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/萧何"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ying-huhai','胡亥','qin','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','秦二世皇帝，赵高矫诏即位，秦政益暴，终致天下反叛。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秦二世"}]',NULL,NULL,'秦二世','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ying-zheng','嬴政','qin','["嬴政","赵政","秦始皇"]','嬴','赵',-259,1,NULL,'year',-210,1,NULL,'year','["皇帝"]','秦庄襄王之子，前247年继位，前238年亲政，平定嫪毐之乱并免除吕不韦的相国职位。秦国此前经商鞅变法、长期兼并战争积累国力，嬴政任用王翦、李斯等，前230年至前221年灭六国，改称皇帝。统一郡县、文字与度量衡，前210年巡行途中去世。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秦始皇"},{"label":"史記/卷006","url":"https://zh.wikisource.org/wiki/史記/卷006"},{"label":"《史记·秦本纪》","url":"https://zh.wikisource.org/wiki/史記/卷005"},{"label":"秦庄襄王纪日及儒略历换算","url":"https://en.wikipedia.org/wiki/King_Zhuangxiang_of_Qin"},{"label":"人物生平与建国经历","url":"https://zh.wikipedia.org/wiki/嬴政"}]',NULL,NULL,'始皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ying-ziying','子婴','qin','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','秦末秦王，赵高废二世后立之，刘邦入关后投降，秦朝终结。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秦王子婴"}]',NULL,NULL,'秦王子婴','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhang-han','章邯','qin','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["将领"]','秦末将领，曾任少府。陈胜起义后率骊山刑徒镇压起义军，击败项梁；巨鹿之战中秦军被项羽击溃后投降项羽，后受封雍王，楚汉战争中败于刘邦。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/章邯"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhang-liang','张良','han-west','[]',NULL,NULL,-250,1,NULL,'year',-186,1,NULL,'year','["政治家","军事家"]','秦末汉初谋臣，字子房，韩国贵族后裔。曾在博浪沙谋刺秦始皇未成，后辅佐刘邦，鸿门宴上助其脱险并参与楚汉决策；汉朝建立后封留侯，晚年退居。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/张良"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhang-qian','张骞','han-west','[]',NULL,NULL,-164,1,NULL,'year',-114,1,NULL,'year','["外交家"]','西汉外交家，汉中成固人。建元年间奉汉武帝命出使大月氏，途中被匈奴拘留十余年后返汉；后再次出使乌孙，推动汉朝与西域诸国往来，被誉为“凿空”。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/张骞"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhao-gao','赵高','qin','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家"]','秦宦官，矫诏立胡亥，指鹿为马，后被子婴诛杀；秦二世自杀后他企图另立秦王子婴，随后被子婴诱杀于斋宫。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/赵高"}]',NULL,NULL,NULL,'[]');
